    this.left = null;
    this.right = null;
  }
}

const preorder = (n, out = []) => {
  if (n) {
    out.push(n.val);
    preorder(n.left, out);
    preorder(n.right, out);
  }
  return out;
};
const inorder = (n, out = []) => {
  if (n) {
    inorder(n.left, out);
    out.push(n.val);
    inorder(n.right, out);
  }
  return out;
};
const postorder = (n, out = []) => {
  if (n) {
    postorder(n.left, out);
    postorder(n.right, out);
    out.push(n.val);
  }
  return out;
};

